'use strict';

/**
 * Turns a GameSpec into a single self-contained HTML file.
 *
 * Rules the bundle honours:
 *  - one file, no build step, opens with a double-click
 *  - Phaser is served from our own origin, so a blocked or slow CDN can never
 *    leave a player staring at a frozen frame with dead buttons
 *  - the shared meamus kit is inlined when spec.runtime.kit is set
 *  - works inside a sandboxed iframe (the SaaS preview) and inside a Cordova
 *    WebView (the APK export)
 */

const templates = require('./templates');

/**
 * Phaser ships from our own origin. The CDN is only a fallback for a bundle
 * saved to disk or dropped into a Cordova www/ directory, where the absolute
 * path does not resolve.
 *
 * This ordering matters. When Phaser came from the CDN first, any network that
 * blocked or throttled jsdelivr produced a page where the canvas never
 * appeared and every button was dead - the exact "games don't start" report.
 */
const PHASER_LOCAL = '/vendor/phaser.min.js';
const PHASER_CDN = (version) => `https://cdn.jsdelivr.net/npm/phaser@${version}/dist/phaser.min.js`;

/* Three.js, for the 3D games, on exactly the same terms: served from our own
   origin first, CDN only as the fallback for a bundle saved to disk or dropped
   into a Cordova www/ directory where the absolute path does not resolve.
   r149 rather than something newer because it is the last release with a real
   UMD build - later ones ship ESM only and warn on the minified global, and a
   generated game written as a classic script needs `THREE` to just be there. */
const THREE_LOCAL = '/vendor/three.min.js';
const THREE_VERSION = '0.149.0';
const THREE_CDN = `https://cdn.jsdelivr.net/npm/three@${THREE_VERSION}/build/three.min.js`;

/** Which engine a spec is written against. Phaser unless it says otherwise. */
function engineOf(spec) {
  return (spec.runtime && spec.runtime.engine) === 'three' ? 'three' : 'phaser';
}

const escapeHtml = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

/** Guard against a </script> inside generated code closing our tag early. */
const escapeScript = (s) => String(s).replace(/<\/(script)/gi, '<\\/$1');

const DEFAULT_CSS = `
* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: #fdf6ec;
  color: #2f2a24;
  font-family: "Trebuchet MS", "Segoe UI", Arial, sans-serif;
  overflow: hidden;
  /* Stop iOS double-tap zoom and pull-to-refresh from fighting the canvas. */
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}
#game-container {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  /* Respect notches on modern phones. */
  padding: env(safe-area-inset-top) env(safe-area-inset-right)
           env(safe-area-inset-bottom) env(safe-area-inset-left);
}
#game-container canvas { display: block; max-width: 100%; max-height: 100%; }
#boot-error {
  position: fixed; inset: 0; display: none; align-items: center; justify-content: center;
  padding: 24px; text-align: center; font-size: 14px; line-height: 1.6; color: #c4503f;
}
#boot-error.show { display: flex; }
@media (prefers-reduced-motion: reduce) { * { animation-duration: 0.001ms !important; } }
`.trim();

/**
 * @param {object} spec normalised GameSpec
 * @param {object} [opts]
 * @param {boolean} [opts.includeKit] override spec.runtime.kit
 * @returns {string} complete HTML document
 */
function bundle(spec, opts = {}) {
  const version = (spec.runtime && spec.runtime.phaserVersion) || '3.60.0';
  const engine = engineOf(spec);
  const useKit = opts.includeKit !== undefined ? opts.includeKit : Boolean(spec.runtime && spec.runtime.kit);
  const title = spec.gameConfig.title || 'meamus game';
  const description = spec.gameConfig.description || '';
  const css = spec.gameCode.css || DEFAULT_CSS;
  const kit = useKit ? templates.readKit() : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover">
<meta name="description" content="${escapeHtml(description)}">
<meta name="theme-color" content="#fdf6ec">
<meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
<title>${escapeHtml(title)}</title>
<style>
${css}
</style>
</head>
<body>
<div id="game-container" role="application" aria-label="${escapeHtml(title)}"></div>
<div id="boot-error"></div>

<!--
  ${escapeHtml(title)} - ${escapeHtml(spec.gameConfig.genre)}
  Generated by meamus. Single file: open it in any browser, or drop it into
  a Cordova/Capacitor www/ directory to ship it as an app.
-->
<script src="${engine === 'three' ? THREE_LOCAL : PHASER_LOCAL}"></script>
<script>
// Same-origin engine is gone (file:// bundle, or a Cordova www/ without it).
// document.write during initial parse inserts a blocking script, so the game
// code below still finds it defined.
if (typeof ${engine === 'three' ? 'THREE' : 'Phaser'} === 'undefined') {
  document.write('<scr' + 'ipt src="${engine === 'three' ? THREE_CDN : PHASER_CDN(version)}"><\\/scr' + 'ipt>');
}
</script>
<script>
// The game needs its engine. Fail loudly instead of rendering a blank canvas.
window.addEventListener('error', function (e) {
  var box = document.getElementById('boot-error');
  if (!box || box.classList.contains('show')) return;
  box.textContent = 'Game error: ' + (e.message || 'unknown');
  box.classList.add('show');
});
if (typeof ${engine === 'three' ? 'THREE' : 'Phaser'} === 'undefined') {
  var box = document.getElementById('boot-error');
  box.textContent = '${engine === 'three' ? 'Three.js' : 'Phaser'} could not be loaded. Check your network connection, then reload.';
  box.classList.add('show');
}
</script>
${useKit ? `<script>\n${escapeScript(kit)}\n</script>` : ''}
<script>
${escapeScript(spec.gameCode.javascript)}
</script>
</body>
</html>`;
}

module.exports = {
  bundle, DEFAULT_CSS, escapeHtml, escapeScript, engineOf,
  PHASER_LOCAL, PHASER_CDN, THREE_LOCAL, THREE_CDN, THREE_VERSION
};
